SELECT e.kind, e.branch_id, r.rolname, NOT r.rolcanlogin AS login_disabled, NOT (r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication OR r.rolbypassrls OR r.rolinherit) AS restricted, r.rolconnlimit, r.rolconfig, NOT EXISTS (SELECT 1 FROM pg_auth_members WHERE member=r.oid) AS no_memberships, has_table_privilege(r.oid,'groundbnb.environment_identity','SELECT') AND has_table_privilege(r.oid,'groundbnb.schema_migrations','SELECT') AS metadata_reads, NOT has_table_privilege(r.oid,'groundbnb.synthetic_identities','SELECT,INSERT,UPDATE,DELETE') AS identities_denied FROM groundbnb.environment_identity e JOIN pg_roles r ON r.rolname=CASE e.kind WHEN 'local' THEN 'groundbnb_local_app' WHEN 'preview' THEN 'groundbnb_preview_app' END WHERE e.singleton;
